def solution(n):
    """
    Generates a FizzBuzz sequence from 1 to n.

    Args:
        n (int): The upper limit of the range (1 <= n <= 100).

    Returns:
        list: A list of strings following FizzBuzz rules.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

