def solution(numerator, denominator):
    """
    Performs division of two numbers safely by handling division by zero error.
    Returns integer result when division is exact, otherwise returns float.

    Args:
        numerator (int): The numerator in the division.
        denominator (int): The denominator in the division.

    Returns:
        str: The result of the division as a string (integer when exact), or an error message if the denominator is zero.
    """
    if denominator == 0:
        return "Error: Division by zero is not allowed."
    result = numerator / denominator
    if numerator % denominator == 0:
        return str(int(result))
    else:
        return str(result)

