def solution(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Args:
    n (int): A non-negative integer (0 <= n <= 12)

    Returns:
    int: The factorial of n

    Raises:
    ValueError: If n is negative or not an integer or greater than 12
    """
    # Check for invalid inputs
    if not isinstance(n, int):
        raise ValueError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be non-negative")
    if n > 12:
        raise ValueError("Input must be <= 12")

    # Base case: factorial of 0 is 1
    if n == 0:
        return 1
    # Recursive case: n! = n * (n-1)!
    else:
        return n * solution(n - 1)

def solution(n):
    """
    Calculate the factorial of a non-negative integer n using recursion.

    Args:
    n (int or float): A number that should be a non-negative integer (0 <= n <= 12)

    Returns:
    int: The factorial of n

    Raises:
    ValueError: If n is negative, not an integer, or greater than 12
    TypeError: If n is not a number
    """
    # Check if input is a number at all
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")

    # Check if float input is effectively an integer
    if isinstance(n, float):
        if not n.is_integer():
            raise ValueError("Input must be an integer")
        n = int(n)

    # Check remaining constraints
    if n < 0:
        raise ValueError("Input must be non-negative")
    if n > 12:
        raise ValueError("Input must be <= 12")

    # Base case: factorial of 0 is 1
    if n == 0:
        return 1
    # Recursive case: n! = n * (n-1)!
    else:
        return n * solution(n - 1)

