def solution(coins, amount):
    dp = [0] * (amount + 1)
    dp[0] = 1  # There's one way to make amount 0

    unique_coins = list(set(coins))  # Remove duplicates
    unique_coins.sort()  # Optional: sort to process smaller coins first

    for coin in unique_coins:
        for i in range(coin, amount + 1):
            dp[i] += dp[i - coin]

    return dp[amount]

