def solution(num1, num2, operator):
    """
    Performs a mathematical operation on two numbers with error handling.

    Args:
        num1 (float or int): The first number.
        num2 (float or int): The second number.
        operator (str): The mathematical operator (+, -, *, /).

    Returns:
        float or str: The result of the operation as a float, or "Error" if an error occurs.
    """
    try:
        if operator == "+":
            result = num1 + num2
        elif operator == "-":
            result = num1 - num2
        elif operator == "*":
            result = num1 * num2
        elif operator == "/":
            if num2 == 0:
                return "Error"
            result = num1 / num2
        else:
            return "Error"
        return float(result)
    except:
        return "Error"

