def solution(arr):
    """
    Sorts the input array in ascending order and validates the sorting process.

    Parameters:
    arr (list): The input array of integers to be sorted.

    Returns:
    str or list: "No Reorder Needed" if already sorted, the sorted array if sorting was needed,
                 or an error message if the input is invalid.
    """
    # Check if the input is a list
    if not isinstance(arr, list):
        return "Error: Input must be an array of integers"

    # Check if all elements in the array are integers
    for num in arr:
        if not isinstance(num, int):
            return "Error: Input must be an array of integers"

    # Check if the array is already sorted
    is_sorted = True
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            is_sorted = False
            break

    if is_sorted:
        return "No Reorder Needed"
    else:
        try:
            # Make a copy of the original array to avoid modifying it in place
            sorted_arr = arr.copy()
            sorted_arr.sort()
            return sorted_arr
        except Exception as e:
            return f"Error: {str(e)}"

