data_trail.solution_code:
def solution(arr):
    """
    Fully recursive implementation of Bubble Sort.
    Args:
        arr (list): The list of integers to be sorted.
    Returns:
        list: The sorted list in non-decreasing order.
    """
    def bubble_sort_recursive(arr, n):
        if n == 1:
            return arr

        # Perform one pass of bubble sort
        def bubble_pass(arr, i, n, swapped):
            if i == n - 1:
                return swapped

            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True

            return bubble_pass(arr, i + 1, n, swapped)

        swapped = bubble_pass(arr, 0, n, False)

        # If no swaps occurred, array is sorted
        if not swapped:
            return arr

        # Recur for remaining elements
        return bubble_sort_recursive(arr, n - 1)

    # Make a copy to avoid modifying original array
    arr_copy = arr.copy()
    return bubble_sort_recursive(arr_copy, len(arr_copy))

