def solution(employee_ids, attendance_logs):
    # Create a set from attendance logs for O(1) membership testing
    present_ids = set(attendance_logs)

    # Initialize result dictionary
    status_dict = {}

    # Check each employee's status
    for emp_id in employee_ids:
        if emp_id in present_ids:
            status_dict[emp_id] = "Present"
        else:
            status_dict[emp_id] = "Absent"

    return status_dict

def solution(nums, target):
    def find_first(nums, target):
        left, right = 0, len(nums) - 1
        first = -1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                first = mid
                right = mid - 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return first

    def find_last(nums, target):
        left, right = 0, len(nums) - 1
        last = -1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                last = mid
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first_pos = find_first(nums, target)
    if first_pos == -1:
        return [-1, -1]
    last_pos = find_last(nums, target)
    return [first_pos, last_pos]

