def solution(nums):
    """
    Find the length of the longest strictly increasing subsequence.

    Args:
    nums (List[int]): List of integers.

    Returns:
    int: Length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    # Initialize a list `dp` where dp[i] represents the length of the longest
    # increasing subsequence that ends at index i.
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

