def solution(nums):
    """
    Compute the length of the longest strictly increasing subsequence (LIS) in nums.

    This solution employs dynamic programming where dp[i] represents the length of the LIS ending at index i.
    For each element in nums, we compare it with all previous elements to update the dp array.

    Args:
        nums: List[int] - The input array of integers.

    Returns:
        int - The length of the longest strictly increasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # Initialize dp array with 1s since each element is a LIS of length 1

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

