def solution(nums):
    if not nums:
        return 0

    tails = []
    for num in nums:
        # Binary search to find the position to replace or extend
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid
        # If the position is at the end, append the num
        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num
    return len(tails)

