def solution(numerator, denominator):
    """
    This function performs a robust division of two integers provided as strings.
    It handles various error cases including division by zero, invalid input, and
    results exceeding 32-bit integer limits. The result is returned as a string
    formatted to two decimal places or an appropriate error message.
    """

    # Function to check if a string represents a valid integer
    def is_valid_integer(s):
        s = s.strip()  # Remove leading/trailing whitespace
        if not s:  # Empty string after stripping
            return False
        # Check if the string matches the pattern of an integer with optional sign
        if s[0] in '+-':
            num_str = s[1:]
        else:
            num_str = s
        # Check if the remaining string consists only of digits
        return num_str.isdigit()

    # Function to convert a valid integer string to an integer
    def str_to_int(s):
        s = s.strip()
        if s[0] == '-':
            return -int(s[1:])
        elif s[0] == '+':
            return int(s[1:])
        else:
            return int(s)

    # Check if inputs are valid integers
    if not is_valid_integer(numerator) or not is_valid_integer(denominator):
        return "Error: Invalid input."

    # Convert the strings to integers
    try:
        num = str_to_int(numerator)
        den = str_to_int(denominator)
    except:
        return "Error: Invalid input."

    # Check for division by zero
    if den == 0:
        return "Error: Division by zero."

    # Perform the division
    result = num / den

    # Check if the result exceeds 32-bit integer limits
    if result < -2**31 or result > 2**31 - 1:
        return "Error: Result exceeds 32-bit integer limits."

    # Format the result to two decimal places as a string
    return "{0:.2f}".format(result)

