def solution(numerator, denominator):
    # Check for negative inputs
    if numerator < 0 or denominator < 0:
        return "Error: Negative input"

    # Check for division by zero
    if denominator == 0:
        return "Error: Division by zero"

    # Perform the division
    result = numerator / denominator

    # Check if the division is exact (no remainder)
    if numerator % denominator == 0:
        return str(int(result))
    else:
        # Format the result to two decimal places
        return "{:.2f}".format(result)

def solution(number):
    """
    Classify the given number based on its value and magnitude.

    Args:
    number (int): The integer to classify.

    Returns:
    str: The classification of the number.
    """
    if number == 0:
        return "Zero"
    elif number > 0:
        if number > 100:
            return "Large Positive"
        else:
            return "Positive"
    else:
        if number < -100:
            return "Very Small Negative"
        else:
            return "Negative"

