def solution(amount, coins):
    # Initialize a DP array where dp[i] represents the minimum number of coins needed for amount i
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins needed for amount 0

    for coin in coins:
        # For each coin, update the dp array for all amounts >= coin
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1

    # If dp[amount] is still infinity, return -1 (impossible)
    return dp[amount] if dp[amount] != float('inf') else -1

