def solution(amount, coins):
    if amount < 0:
        return -1
    if amount == 0:
        return 0

    # Filter out invalid coins (non-positive values)
    valid_coins = [coin for coin in coins if coin > 0]
    if not valid_coins:
        return -1

    # Initialize DP array
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins needed for amount 0

    # Process coins in any order
    for coin in valid_coins:
        for i in range(coin, amount + 1):
            if dp[i - coin] + 1 < dp[i]:
                dp[i] = dp[i - coin] + 1

    return dp[amount] if dp[amount] != float('inf') else -1

def solution(n, commands):
    inventory = {}
    output = []

    for cmd in commands:
        parts = cmd.split()
        operation = parts[0]

        if operation == "ADD":
            item_id = parts[1]
            item_name = parts[2]
            quantity = int(parts[3])

            if item_id in inventory:
                inventory[item_id]['quantity'] += quantity
            else:
                inventory[item_id] = {'name': item_name, 'quantity': quantity}

        elif operation == "REMOVE":
            item_id = parts[1]
            quantity = int(parts[2])

            if item_id in inventory:
                if inventory[item_id]['quantity'] <= quantity:
                    del inventory[item_id]
                else:
                    inventory[item_id]['quantity'] -= quantity

        elif operation == "QUERY":
            item_id = parts[1]

            if item_id in inventory:
                output.append(inventory[item_id]['quantity'])
            else:
                output.append("Item not found")

    return output

