from typing import List, Dict, Union

def manage_inventory(products: List[Dict[str, Union[int, str]]]) -> List[Dict[str, Union[int, str]]]:
    restocked_products = []

    for product in products:
        if product['current_stock'] <= product['reorder_level']:
