from typing import List, Dict, Union

def solution(products: List[Dict[str, Union[int, str]]]) -> List[Dict[str, Union[int, str]]]:
    restocked_products = []

    for product in products:
        if product['current_stock'] < product['reorder_level']:
            restocked_product = product.copy()
            restocked_product['restock_amount'] = product['reorder_quantity']
            restocked_products.append(restocked_product)

    return restocked_products
